INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2000, 'devote', '/dɪˈvoʊt/', 'verb', '{"zh-TW":["奉獻；投入"],"en":["to give time or resources to something","to give time, effort, or resources to something"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"vote","meaning":"vow (發誓)"},"logic":"完全發誓投入，即「奉獻」。"}', 'devote time/energy to; devote time to / devote oneself to', '[{"en":"He devoted his career to public service.","zh-TW":"他把職業生涯奉獻給了公共服務。"},{"en":"She devotes two hours daily to exercise.","zh-TW":"她每天投入兩小時運動。"},{"en":"He devoted his career to scientific research.","zh-TW":"他將職業生涯奉獻給科學研究。"},{"en":"She devotes several hours a week to volunteering.","zh-TW":"她每週投入幾個小時做志工。"}]', '{"noun":"devotion","verb":"devote","adjective":"devoted"}', NULL, 2, 2000, NULL),
(2001, 'diagnose', '/ˌdaɪəɡˈnoʊz/', 'verb', '{"zh-TW":["診斷"],"en":["to identify a disease or problem"]}', NULL, 'diagnose a condition', '[{"en":"The doctor diagnosed him with diabetes.","zh-TW":"醫生診斷他患有糖尿病。"},{"en":"The technician diagnosed the issue quickly.","zh-TW":"技術人員很快診斷出了問題。"}]', '{"noun":"diagnosis","verb":"diagnose","adjective":"diagnostic"}', NULL, 3, 2001, NULL),
(2002, 'diagnosis', '/ˌdaɪəɡˈnəʊsɪs/', 'noun', '{"zh-TW":["診斷"],"en":["the identification of an illness from its symptoms"]}', NULL, 'receive a diagnosis / accurate diagnosis', '[{"en":"She received a diagnosis of high blood pressure.","zh-TW":"她被診斷出患有高血壓。"},{"en":"A correct diagnosis is essential for proper treatment.","zh-TW":"正確的診斷對於適當治療至關重要。"}]', '{"verb":"diagnose","adjective":"diagnostic"}', NULL, 3, 2002, NULL),
(2003, 'dialectical', '/ˌdaɪəˈlektɪkəl/', 'adjective', '{"zh-TW":["辯證的；辯證法的"],"en":["relating to logical discussion of opposing ideas"]}', NULL, 'dialectical approach / dialectical tension / dialectical method', '[{"en":"The paper presents a dialectical analysis of competing theories.","zh-TW":"論文對競爭理論進行辯證分析。"},{"en":"Dialectical reasoning helps resolve contradictions in an argument.","zh-TW":"辯證推理有助於解決論點中的矛盾。"}]', '{"noun":"dialectic","adverb":"dialectically"}', NULL, 4, 2003, NULL),
(2004, 'dichotomize', '/daɪˈkɒtəmaɪz/', 'verb', '{"zh-TW":["二分化；將…分為兩類"],"en":["to divide into two contrasting groups"]}', NULL, 'dichotomize variables / dichotomize society / falsely dichotomize', '[{"en":"Researchers sometimes dichotomize continuous variables for convenience.","zh-TW":"研究員有時為了方便將連續變量二分化。"},{"en":"We should not dichotomize complex political views into two camps.","zh-TW":"我們不應該將複雜的政治觀點二分為兩個陣營。"}]', '{"noun":"dichotomy","adjective":"dichotomous"}', NULL, 4, 2004, NULL),
(2005, 'dichotomy', '/daɪˈkɒtəmi/', 'noun', '{"zh-TW":["二元對立；二分法"],"en":["a division into two opposite groups"]}', NULL, 'false dichotomy / clear dichotomy / public-private dichotomy', '[{"en":"The study reveals a dichotomy between urban and rural outcomes.","zh-TW":"研究揭示了城鄉結果之間的二元對立。"},{"en":"This is a false dichotomy — there are other options available.","zh-TW":"這是一個錯誤的二分法——還有其他選擇。"}]', '{"adjective":"dichotomic"}', NULL, 3, 2005, NULL),
(2006, 'dictionary', '/ˈdɪkʃənɛri/', 'noun', '{"zh-TW":["字典"],"en":["a book that lists words and their meanings"]}', NULL, 'look up in a dictionary / online dictionary', '[{"en":"Use a dictionary to check the spelling.","zh-TW":"用字典查看拼寫。"},{"en":"Online dictionaries are very convenient.","zh-TW":"線上字典非常方便。"}]', '{"noun":"dictionary"}', NULL, 4, 2006, NULL),
(2007, 'die', '/daɪ/', 'verb', '{"zh-TW":["死亡"],"en":["to stop living"]}', NULL, 'die of / die out', '[{"en":"Many soldiers died in the war.","zh-TW":"許多士兵在戰爭中死亡。"},{"en":"The species is dying out.","zh-TW":"這個物種正在滅絕。"}]', '{"noun":"death","adjective":"dead"}', NULL, 1, 2007, NULL),
(2008, 'dietary fiber', '/''daɪətəri ˌfaɪbər/', 'noun', '{"zh-TW":["膳食纖維"],"en":["the indigestible portion of plant foods that helps maintain digestive health"]}', NULL, 'high in dietary fiber / consume dietary fiber / dietary fiber content', '[{"en":"Vegetables, fruits, and whole grains are rich sources of dietary fiber.","zh-TW":"蔬菜、水果和全穀類是膳食纖維的豐富來源。"},{"en":"A diet high in dietary fiber reduces the risk of colon cancer and digestive problems.","zh-TW":"富含膳食纖維的飲食可以降低結腸癌和消化問題的風險。"}]', NULL, NULL, 5, 2008, NULL),
(2009, 'dietary guideline', '/''daɪətəri ˌɡaɪdlaɪn/', 'noun', '{"zh-TW":["飲食指南；膳食指引"],"en":["official recommendations about the types and amounts of food that promote health"]}', NULL, 'follow dietary guidelines / national dietary guideline / update dietary guidelines', '[{"en":"Dietary guidelines recommend at least five servings of fruits and vegetables daily.","zh-TW":"飲食指南建議每天至少食用五份水果和蔬菜。"},{"en":"Health agencies revise their dietary guidelines every few years based on new research.","zh-TW":"衛生機構每隔幾年根據新研究修訂飲食指南。"}]', NULL, NULL, 5, 2009, NULL),
(2010, 'dietary restriction', '/ˈdaɪətəri rɪˈstrɪkʃən/', 'noun', '{"zh-TW":["飲食限制"],"en":["a limitation on what foods can be consumed"]}', NULL, 'notify about dietary restrictions / common dietary restriction', '[{"en":"Please inform us of any dietary restrictions in advance.","zh-TW":"請提前告知我們任何飲食限制。"},{"en":"We can accommodate most dietary restrictions upon request.","zh-TW":"我們可以根據要求滿足大多數飲食限制。"}]', '{"adjective":"dietary","verb":"restrict"}', NULL, 5, 2010, NULL),
(2011, 'dietary supplement', '/ˈdaɪətəri ˈsʌplɪmənt/', 'noun', '{"zh-TW":["膳食補充品"],"en":["a product taken to add nutrients to the diet"]}', NULL, 'take a dietary supplement / dietary supplement label', '[{"en":"Vitamin D is a common dietary supplement.","zh-TW":"維生素D是常見的膳食補充品。"},{"en":"Always consult a doctor before taking dietary supplements.","zh-TW":"服用膳食補充品前務必諮詢醫生。"}]', NULL, NULL, 5, 2011, NULL),
(2012, 'differ', '/ˈdɪfər/', 'verb', '{"zh-TW":["不同；相異"],"en":["to be unlike or distinct"]}', NULL, 'differ from/in', '[{"en":"Opinions differ on this issue.","zh-TW":"對這個問題意見不一。"},{"en":"The two products differ significantly in quality.","zh-TW":"這兩個產品在品質上有很大差異。"}]', '{"noun":"difference","verb":"differ","adjective":"different","adverb":"differently"}', NULL, 2, 2012, NULL),
(2013, 'difference', '/ˈdɪfərəns/', 'noun', '{"zh-TW":["差異；不同"],"en":["the way in which things are not the same"]}', NULL, 'make a difference / tell the difference', '[{"en":"Can you tell the difference?","zh-TW":"你能分辨出差異嗎？"},{"en":"Small actions can make a big difference.","zh-TW":"小小的行動可以帶來很大的改變。"}]', '{"adjective":"different","verb":"differ","adverb":"differently"}', NULL, 4, 2013, 332),
(2014, 'differential pricing', '/ˌdɪfəˈrenʃəl ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["差異化定價"],"en":["a strategy of charging different prices to different customers for the same product"]}', NULL, 'implement differential pricing / differential pricing model', '[{"en":"Airlines use differential pricing by charging more for peak-time flights.","zh-TW":"航空公司通過對高峰時段航班收取更多費用來實施差異化定價。"},{"en":"Differential pricing maximizes revenue across different customer segments.","zh-TW":"差異化定價在不同客戶群體中最大化了收入。"}]', NULL, NULL, 5, 2014, NULL),
(2015, 'differentiate', '/ˌdɪfəˈrenʃieɪt/', 'verb', '{"zh-TW":["區分；差異化"],"en":["to make or show a distinction between things or oneself from competitors"]}', NULL, 'differentiate the brand / differentiate from competitors', '[{"en":"The company differentiated itself through superior customer service.","zh-TW":"公司通過卓越的客戶服務實現了差異化。"},{"en":"It is important to differentiate between fixed and variable costs.","zh-TW":"區分固定成本和變動成本非常重要。"}]', '{"noun":"differentiation","adjective":"differentiated"}', NULL, 5, 2015, 668),
(2016, 'differentiated product', '/ˌdɪfəˈrenʃieɪtɪd ˈprɒdʌkt/', 'noun', '{"zh-TW":["差異化產品"],"en":["a product with distinct features that set it apart from competitors"]}', NULL, 'launch a differentiated product / create a differentiated product', '[{"en":"The company launched a differentiated product with a unique design.","zh-TW":"公司推出了具有獨特設計的差異化產品。"},{"en":"Differentiated products can support higher pricing and brand loyalty.","zh-TW":"差異化產品可以支持更高定價和品牌忠誠度。"}]', NULL, NULL, 5, 2016, NULL),
(2017, 'differentiation', '/ˌdɪfərənʃiˈeɪʃən/', 'noun', '{"zh-TW":["差異化"],"en":["the process of distinguishing a product from competitors"]}', NULL, 'product differentiation / competitive differentiation / differentiation strategy', '[{"en":"Price differentiation alone is rarely sustainable long-term.","zh-TW":"僅靠價格差異化很少能長期維持。"},{"en":"Technology differentiation gave the firm a significant market advantage.","zh-TW":"技術差異化給公司帶來了顯著的市場優勢。"}]', '{"verb":"differentiate","adjective":"differentiated"}', NULL, 5, 2017, 547),
(2018, 'difficult', '/ˈdɪfɪkəlt/', 'adjective', '{"zh-TW":["困難的"],"en":["not easy to do or understand"]}', NULL, 'difficult question / difficult situation', '[{"en":"The exam was very difficult.","zh-TW":"考試非常困難。"},{"en":"She''s in a difficult situation.","zh-TW":"她處於困難的處境中。"}]', '{"noun":"difficulty"}', NULL, 3, 2018, NULL),
(2019, 'dig', '/dɪɡ/', 'verb', '{"zh-TW":["挖掘"],"en":["to make a hole in the ground"]}', NULL, 'dig a hole / dig up', '[{"en":"The dog dug a hole in the garden.","zh-TW":"狗在花園裡挖了一個洞。"},{"en":"They dug up some old coins.","zh-TW":"他們挖出了一些舊硬幣。"}]', NULL, NULL, 1, 2019, NULL),
(2020, 'digestive health', '/''daɪˌdʒestɪv helθ/', 'noun', '{"zh-TW":["消化健康"],"en":["the overall condition and functioning of the digestive system"]}', NULL, 'promote digestive health / improve digestive health / digestive health supplement', '[{"en":"Eating enough fiber daily is one of the best ways to maintain digestive health.","zh-TW":"每天攝入足夠的纖維是維持消化健康的最佳方式之一。"},{"en":"Stress management is often overlooked but crucial for long-term digestive health.","zh-TW":"壓力管理常被忽視，但對長期消化健康至關重要。"}]', '{"adjective":"digestive"}', NULL, 5, 2020, NULL),
(2021, 'digestive system', '/''daɪˌdʒestɪv ˌsɪstəm/', 'noun', '{"zh-TW":["消化系統"],"en":["the organs in the body that are involved in breaking down food and absorbing nutrients"]}', NULL, 'support the digestive system / healthy digestive system / digestive system disorder', '[{"en":"A balanced diet helps maintain a healthy digestive system.","zh-TW":"均衡飲食有助於維持健康的消化系統。"},{"en":"Stress can negatively affect the digestive system and cause discomfort.","zh-TW":"壓力會對消化系統產生負面影響並引起不適。"}]', NULL, NULL, 5, 2021, NULL),
(2022, 'digital', '/ˈdɪdʒɪtəl/', 'adjective', '{"zh-TW":["數位的；數碼的","數位的"],"en":["relating to computer technology or electronic data","using electronic technology"]}', NULL, 'digital transformation; digital camera / digital transformation', '[{"en":"The company is undergoing a digital transformation.","zh-TW":"公司正在進行數位轉型。"},{"en":"Digital marketing is essential today.","zh-TW":"數位行銷在今天是必不可少的。"},{"en":"We live in the digital age.","zh-TW":"我們生活在數位時代。"},{"en":"The company is undergoing digital transformation.","zh-TW":"公司正在進行數位轉型。"}]', '{"noun":"digitization","adjective":"digital","adverb":"digitally","verb":"digitize"}', NULL, 3, 2022, 333),
(2023, 'digital infrastructure', '/ˈdɪdʒɪtəl ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["數位基礎設施"],"en":["the technology systems that support digital business operations"]}', NULL, 'build digital infrastructure / invest in digital infrastructure', '[{"en":"Investing in digital infrastructure is essential for long-term competitiveness.","zh-TW":"投資數位基礎設施對長期競爭力至關重要。"},{"en":"Weak digital infrastructure creates bottlenecks in operations.","zh-TW":"薄弱的數位基礎設施在運營中造成瓶頸。"}]', NULL, NULL, 5, 2023, NULL),
(2024, 'digital literacy', '/''dɪdʒɪtəl ˌlɪtərəsi/', 'noun', '{"zh-TW":["數字素養；數位素養"],"en":["the ability to use digital technologies effectively, safely, and thoughtfully"]}', NULL, 'develop digital literacy / digital literacy skills / digital literacy education', '[{"en":"Digital literacy is now considered an essential skill for both students and professionals.","zh-TW":"數字素養現在被認為是學生和專業人士的基本技能。"},{"en":"Schools are incorporating digital literacy into their curricula to prepare students for the future.","zh-TW":"學校正在將數字素養納入其課程，為學生的未來做好準備。"}]', '{"adjective":"digitally literate"}', NULL, 5, 2024, NULL),
(2025, 'digital marketing', '/ˈdɪdʒɪtəl ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["數位行銷"],"en":["marketing conducted through digital channels"]}', NULL, 'digital marketing strategy / digital marketing campaign', '[{"en":"Digital marketing has become the dominant form of advertising.","zh-TW":"數位行銷已成為主要的廣告形式。"},{"en":"The company''s digital marketing team manages social media accounts.","zh-TW":"公司的數位行銷團隊管理社交媒體帳號。"}]', NULL, NULL, 5, 2025, NULL),
(2026, 'digital payment', '/ˈdɪdʒɪtəl ˈpeɪmənt/', 'noun', '{"zh-TW":["數字支付；電子支付"],"en":["payment made electronically via mobile apps, online banking, or digital wallets"]}', NULL, 'accept digital payments / digital payment platform', '[{"en":"Digital payments account for over 70% of consumer transactions in the region.","zh-TW":"數字支付佔該地區消費者交易的70%以上。"},{"en":"The company integrated multiple digital payment options to improve checkout.","zh-TW":"公司整合了多種數字支付選項以改善結帳流程。"}]', '{"synonym":"electronic payment","synonym2":"e-payment"}', NULL, 5, 2026, NULL),
(2027, 'digital signature', '/ˈdɪdʒɪtəl ˈsɪɡnətʃər/', 'noun', '{"zh-TW":["數位簽章；電子簽名"],"en":["an electronic method of signing documents securely"]}', NULL, 'apply a digital signature / verify a digital signature', '[{"en":"Documents can be signed using a legally valid digital signature.","zh-TW":"文件可以使用具有法律效力的數位簽章簽署。"},{"en":"The digital signature confirmed the document''s authenticity.","zh-TW":"數位簽章確認了文件的真實性。"}]', NULL, NULL, 5, 2027, NULL),
(2028, 'digital transformation', '/ˈdɪdʒɪtl ˌtrænsfəˈmeɪʃən/', 'noun', '{"zh-TW":["數位轉型"],"en":["integrating digital technology into all areas of a business to fundamentally change operations"]}', NULL, 'digital transformation strategy / digital transformation journey / lead digital transformation', '[{"en":"The company''s digital transformation reduced manual processes by 60%.","zh-TW":"公司的數位轉型將手動流程減少了60%。"},{"en":"Digital transformation requires cultural change as much as technology.","zh-TW":"數位轉型需要文化變革，與技術同等重要。"}]', '{"verb":"digitally transform","adjective":"digital"}', NULL, 5, 2028, NULL),
(2029, 'digital twin', '/ˈdɪdʒɪtəl twɪn/', 'noun', '{"zh-TW":["數位孿生"],"en":["a virtual replica of a physical object or system used for simulation"]}', NULL, 'create a digital twin / digital twin model / industrial digital twin', '[{"en":"Manufacturers use digital twins to simulate production processes before implementation.","zh-TW":"製造商使用數位孿生在實施前模擬生產流程。"},{"en":"A digital twin of the power grid allows operators to test scenarios safely.","zh-TW":"電網的數位孿生允許運營商安全地測試場景。"}]', NULL, NULL, 4, 2029, NULL),
(2030, 'diligence', '/ˈdɪlɪdʒəns/', 'noun', '{"zh-TW":["盡職調查；勤奮"],"en":["careful and persistent work; also thorough investigation before a transaction"]}', NULL, 'due diligence / financial diligence / exercise diligence', '[{"en":"The acquirer conducted extensive due diligence before completing the deal.","zh-TW":"收購方在完成交易前進行了廣泛的盡職調查。"},{"en":"Her diligence and attention to detail made her invaluable to the team.","zh-TW":"她的勤奮和注重細節使她成為團隊不可或缺的一員。"}]', '{"adjective":"diligent","adverb":"diligently"}', NULL, 3, 2030, NULL),
(2031, 'diligent', '/ˈdɪlɪdʒənt/', 'adjective', '{"zh-TW":["勤勉的；勤奮的"],"en":["showing care and effort in one''s work"]}', NULL, 'diligent worker/student', '[{"en":"She is a diligent employee who always meets her goals.","zh-TW":"她是一位勤勉的員工，總是達成目標。"},{"en":"Diligent research led to the breakthrough.","zh-TW":"勤勉的研究促成了突破。"}]', '{"noun":"diligence","adjective":"diligent","adverb":"diligently"}', NULL, 3, 2031, NULL),
(2032, 'dilution', '/daɪˈluːʃən/', 'noun', '{"zh-TW":["稀釋；股權稀釋"],"en":["the reduction in existing shareholders'' ownership percentage due to new share issuance"]}', NULL, 'equity dilution / avoid dilution / dilution of ownership', '[{"en":"New investors accepted the funding knowing it would cause dilution.","zh-TW":"新投資者在知道會造成稀釋的情況下接受了融資。"},{"en":"Anti-dilution provisions protect early investors in future rounds.","zh-TW":"反稀釋條款在未來融資輪次中保護早期投資者。"}]', '{"verb":"dilute","adjective":"diluted"}', NULL, 3, 2032, NULL),
(2033, 'dilutive', '/daɪˈljuːtɪv/', 'adjective', '{"zh-TW":["稀釋性的"],"en":["having the effect of reducing earnings per share or ownership percentage"]}', NULL, 'dilutive effect / dilutive issuance / dilutive transaction', '[{"en":"The new share issuance is expected to be dilutive to existing shareholders.","zh-TW":"新股發行預計對現有股東具有稀釋效應。"},{"en":"Options and warrants are potentially dilutive securities.","zh-TW":"期權和認股權證是潛在的稀釋性證券。"}]', '{"noun":"dilution","verb":"dilute"}', NULL, 3, 2033, NULL),
(2034, 'dimension', '/daɪˈmenʃn/', 'noun', '{"zh-TW":["尺寸；維度；層面"],"en":["a measurable extent","an aspect of something"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"mens","meaning":"measure (測量)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"分開測量的各面向，即「維度」。"}', 'new dimension / three-dimensional', '[{"en":"The room''s dimensions are 5 by 4 meters.","zh-TW":"房間的尺寸是5乘4公尺。"},{"en":"This adds a new dimension to the problem.","zh-TW":"這為問題增添了新的層面。"}]', '{"adjective":"dimensional"}', NULL, 3, 2034, NULL),
(2035, 'diminish', '/dɪˈmɪnɪʃ/', 'verb', '{"zh-TW":["減少；縮小","減少；削弱"],"en":["to make or become less"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"min","meaning":"small (小)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使變小，即「減少」。"}', 'diminish in value/importance; diminish in value / diminishing returns', '[{"en":"The value of the investment has diminished.","zh-TW":"投資的價值已經減少。"},{"en":"Nothing can diminish her achievements.","zh-TW":"沒有什麼能削弱她的成就。"},{"en":"His influence has diminished over the years.","zh-TW":"他的影響力逐年減弱。"}]', '{"verb":"diminish","adjective":"diminished"}', NULL, 3, 2035, 669),
(2036, 'diminishing returns', '/''dɪˌmɪnɪʃɪŋ rɪˌtɜːrnz/', 'noun', '{"zh-TW":["邊際效益遞減；報酬遞減"],"en":["a situation in which adding more of one factor eventually yields smaller increases in output"]}', NULL, 'experience diminishing returns / law of diminishing returns / hit diminishing returns', '[{"en":"After a certain point, additional advertising investment leads to diminishing returns.","zh-TW":"超過某一點後，額外的廣告投資會導致邊際效益遞減。"},{"en":"The team recognized diminishing returns and decided to redirect resources elsewhere.","zh-TW":"團隊認識到報酬遞減，決定將資源重新分配到其他地方。"}]', '{"adjective":"diminishing","verb":"diminish"}', NULL, 5, 2036, NULL),
(2037, 'diner', '/ˈdaɪnər/', 'noun', '{"zh-TW":["用餐者；小餐館"],"en":["a person eating at a restaurant, or a small restaurant"]}', NULL, 'dine at a diner / regular diner', '[{"en":"The diner across the street is open 24 hours.","zh-TW":"街對面的小餐館全天24小時開放。"},{"en":"Every diner received a complimentary glass of wine.","zh-TW":"每位用餐者獲得了一杯免費葡萄酒。"}]', '{"verb":"dine"}', NULL, 2, 2037, NULL),
(2038, 'dining experience', '/ˈdaɪnɪŋ ɪkˈspɪəriəns/', 'noun', '{"zh-TW":["用餐體驗"],"en":["the overall impression of eating at a restaurant"]}', NULL, 'memorable dining experience / fine dining experience', '[{"en":"The restaurant offers an unforgettable dining experience.","zh-TW":"這家餐廳提供難忘的用餐體驗。"},{"en":"A good dining experience goes beyond just the food.","zh-TW":"良好的用餐體驗不僅僅是食物。"}]', NULL, NULL, 5, 2038, NULL),
(2039, 'dinner', '/ˈdɪnər/', 'noun', '{"zh-TW":["晚餐"],"en":["the main meal of the day, usually in the evening","the main meal of the day"]}', NULL, 'business dinner / dinner party; dinner party / have dinner', '[{"en":"We have a business dinner tonight.","zh-TW":"我們今晚有商務晚餐。"},{"en":"Shall we go out for dinner?","zh-TW":"我們出去吃晚餐好嗎？"},{"en":"What''s for dinner tonight?","zh-TW":"今晚晚餐吃什麼？"},{"en":"Let''s have dinner together.","zh-TW":"一起吃晚餐吧。"}]', '{"noun":"dinner"}', NULL, 2, 2039, NULL),
(2040, 'diploma', '/dɪˈploʊmə/', 'noun', '{"zh-TW":["文憑；畢業證書"],"en":["a certificate awarded after completing a course"]}', NULL, 'high school diploma / diploma program', '[{"en":"He received his diploma at graduation.","zh-TW":"他在畢業典禮上拿到了文憑。"},{"en":"A diploma is required for this job.","zh-TW":"這份工作需要文憑。"}]', NULL, NULL, 3, 2040, NULL),
(2041, 'diplomatic', '/ˌdɪpləˈmætɪk/', 'adjective', '{"zh-TW":["外交的；圓融的"],"en":["relating to managing international relations"]}', NULL, 'diplomatic relations / diplomatic immunity', '[{"en":"They broke off diplomatic relations.","zh-TW":"他們斷絕了外交關係。"},{"en":"She handled the situation diplomatically.","zh-TW":"她圓融地處理了這個情況。"}]', '{"noun":"diplomacy","noun2":"diplomat"}', NULL, 4, 2041, NULL),
(2042, 'diplomatic language', '/''dɪpləˌmætɪk ˌlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["外交語言；外交措辭"],"en":["carefully chosen language used to avoid offense or conflict while still conveying a message"]}', NULL, 'use diplomatic language / choose diplomatic language / master diplomatic language', '[{"en":"He used diplomatic language to reject the proposal without damaging the relationship.","zh-TW":"他使用外交語言拒絕了提案，而沒有損害雙方關係。"},{"en":"Mastering diplomatic language is essential for international negotiators.","zh-TW":"掌握外交語言對國際談判者至關重要。"}]', NULL, NULL, 5, 2042, NULL),
(2043, 'direct', '/dɪˈrekt/', 'verb / adjective', '{"zh-TW":["指導；直接的","直接的"],"en":["to manage; without anything in between","going straight without stopping"]}', NULL, 'direct contact/access; direct flight / direct contact', '[{"en":"She directs the marketing department.","zh-TW":"她指導行銷部門。"},{"en":"Is there a direct flight to Tokyo?","zh-TW":"有直飛東京的航班嗎？"},{"en":"He gave a direct answer.","zh-TW":"他給了一個直接的回答。"}]', '{"noun":"direction/director","verb":"direct","adjective":"direct","adverb":"directly","noun2":"director"}', NULL, 2, 2043, 25),
(2044, 'direct cost', '/dɪˈrekt kɒst/', 'noun', '{"zh-TW":["直接成本"],"en":["a cost that can be directly attributed to producing a product or service"]}', NULL, 'reduce direct costs / allocate direct costs', '[{"en":"Direct costs include raw materials, packaging, and direct labor.","zh-TW":"直接成本包括原材料、包裝和直接人工。"},{"en":"Reducing direct costs improves the gross profit margin.","zh-TW":"降低直接成本改善了毛利率。"}]', '{"plural":"direct costs","opposite":"indirect cost"}', NULL, 4, 2044, NULL),
(2045, 'direct debit', '/dɪˈrekt ˈdebɪt/', 'noun', '{"zh-TW":["直接扣帳；自動轉帳"],"en":["authorization allowing a company to collect payments from a bank account automatically"]}', NULL, 'set up a direct debit / cancel a direct debit', '[{"en":"Utility bills are paid by direct debit on the first of each month.","zh-TW":"水電費在每月第一日通過直接扣帳支付。"},{"en":"Setting up a direct debit ensures bills are never missed.","zh-TW":"設置直接扣帳確保永遠不會錯過賬單。"}]', NULL, NULL, 4, 2045, NULL),
(2046, 'direct flight', '/dɪˈrɛkt flaɪt/', 'noun', '{"zh-TW":["直飛航班"],"en":["a flight going straight to the destination without stops"]}', NULL, 'book a direct flight / take a direct flight', '[{"en":"There are no direct flights to Vancouver from here.","zh-TW":"從這裡到溫哥華沒有直飛航班。"},{"en":"A direct flight will save us several hours.","zh-TW":"直飛航班將節省我們幾個小時。"}]', NULL, NULL, 5, 2046, NULL),
(2047, 'direct mail', '/dɪˈrekt meɪl/', 'noun', '{"zh-TW":["直郵行銷"],"en":["a marketing technique of sending promotional material directly to targeted customers"]}', NULL, 'run a direct mail campaign / direct mail response rate', '[{"en":"The direct mail campaign generated a 5% response rate.","zh-TW":"直郵行銷活動產生了5%的響應率。"},{"en":"Direct mail is still effective for targeting older demographics.","zh-TW":"直郵行銷對於針對年齡較大的人口群體仍然有效。"}]', NULL, NULL, 4, 2047, NULL),
(2048, 'direct marketing', '/dɪˈrekt ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["直效行銷；直接行銷"],"en":["promoting products directly to target customers without intermediaries"]}', NULL, 'use direct marketing / direct marketing campaign', '[{"en":"Direct marketing via email generated a 10% response rate.","zh-TW":"通過電子郵件的直效行銷產生了10%的回應率。"},{"en":"A direct marketing campaign targeted previous customers with special offers.","zh-TW":"直效行銷活動以特別優惠針對了以前的客戶。"}]', NULL, NULL, 5, 2048, NULL),
(2049, 'direction', 'dɪˈrɛkʃən', 'noun', '{"zh-TW":["方向；指示","指導"],"en":["the way something moves or faces","an instruction"]}', NULL, 'strategic direction/give directions', '[{"en":"The company needs a clear strategic direction.","zh-TW":"公司需要明確的戰略方向。"}]', '{"verb":"direct","adjective":"directional","adverb":"directionally"}', NULL, 3, 2049, 548);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2050, 'directional strategy', '/daɪˈrekʃənl ˈstrætɪdʒi/', 'noun', '{"zh-TW":["方向性策略"],"en":["a high-level plan that sets the overall direction of a company"]}', NULL, 'define directional strategy / communicate the directional strategy', '[{"en":"The board set a clear directional strategy focused on digital transformation.","zh-TW":"董事會制定了聚焦數位轉型的清晰方向性策略。"},{"en":"All business units aligned their plans with the corporate directional strategy.","zh-TW":"所有業務單位使其計劃與公司方向性策略保持一致。"}]', NULL, NULL, 5, 2050, NULL),
(2051, 'directive', '/dɪˈrektɪv/', 'noun', '{"zh-TW":["指令；指示"],"en":["an official or authoritative instruction"]}', NULL, 'issue a directive / comply with the directive / management directive', '[{"en":"A directive was issued requiring all systems to be updated by Friday.","zh-TW":"發出了一項指令，要求所有系統在週五前更新。"},{"en":"Staff were briefed on the new directive during the morning meeting.","zh-TW":"員工在早上的會議上被告知了新指令。"}]', '{"adjective":"directive"}', NULL, 3, 2051, 858),
(2052, 'director', '/daɪˈrektər/', 'noun', '{"zh-TW":["董事；總監"],"en":["a person who heads a department or sits on the board of directors"]}', NULL, 'board director / executive director / sales director / marketing director', '[{"en":"She was appointed marketing director after five years at the firm.","zh-TW":"她在公司工作五年後被任命為行銷總監。"},{"en":"The director presented the quarterly results to the board.","zh-TW":"總監向董事會呈報了季度業績。"}]', '{"plural":"directors","verb":"direct"}', NULL, 3, 2052, 334),
(2053, 'dirty', '/ˈdɜːrti/', 'adjective', '{"zh-TW":["髒的"],"en":["not clean; covered in unwanted substances","not clean"]}', NULL, 'dirty work / get dirty; dirty hands / dirty work', '[{"en":"Someone has to do the dirty work.","zh-TW":"總得有人做苦差事。"},{"en":"The warehouse floor was dirty.","zh-TW":"倉庫地板很髒。"},{"en":"Your hands are dirty.","zh-TW":"你的手很髒。"},{"en":"Nobody wants to do the dirty work.","zh-TW":"沒人想做髒活。"}]', '{"adjective":"dirty","verb":"dirty","noun":"dirt"}', NULL, 2, 2053, NULL),
(2054, 'disability', '/ˌdɪsəˈbɪləti/', 'noun', '{"zh-TW":["殘疾；障礙"],"en":["a physical or mental condition that limits ability"]}', NULL, 'learning/physical disability', '[{"en":"The company provides support for employees with disabilities.","zh-TW":"公司為有殘疾的員工提供支援。"},{"en":"Disability benefits are available for those who qualify.","zh-TW":"符合資格者可獲得殘疾福利。"}]', '{"noun":"disability","verb":"disable","adjective":"disabled"}', NULL, 4, 2054, 335),
(2055, 'disappear', '/ˌdɪsəˈpɪr/', 'verb', '{"zh-TW":["消失"],"en":["to become impossible to see"]}', NULL, 'disappear from view / disappear without a trace', '[{"en":"The sun disappeared behind the clouds.","zh-TW":"太陽消失在雲後面。"},{"en":"He disappeared without a trace.","zh-TW":"他消失得無影無蹤。"}]', '{"noun":"disappearance"}', NULL, 3, 2055, NULL),
(2056, 'disappoint', '/ˌdɪsəˈpɔɪnt/', 'verb', '{"zh-TW":["使失望"],"en":["to fail to fulfill the expectations of"]}', NULL, 'deeply disappointed', '[{"en":"The results disappointed the investors.","zh-TW":"結果讓投資者失望了。"},{"en":"I''m disappointed with the service quality.","zh-TW":"我對服務品質感到失望。"}]', '{"noun":"disappointment","verb":"disappoint","adjective":"disappointing/disappointed"}', NULL, 4, 2056, NULL),
(2057, 'disappointed', '/ˌdɪsəˈpɔɪntɪd/', 'adjective', '{"zh-TW":["失望的"],"en":["sad because something was not as good as expected"]}', '{"prefix":{"text":"dis-","meaning":"not (不)"},"root":{"text":"appoint","meaning":"arrange (安排)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"事情沒有按安排進行的感受，即「失望的」。"}', 'deeply disappointed / disappointed with', '[{"en":"She was disappointed with the test results.","zh-TW":"她對考試成績感到失望。"},{"en":"Fans were disappointed by the team''s performance.","zh-TW":"球迷對球隊的表現感到失望。"}]', '{"noun":"disappointment","adjective":"disappointing"}', NULL, 4, 2057, NULL),
(2058, 'disaster', '/dɪˈzæstər/', 'noun', '{"zh-TW":["災難"],"en":["a sudden event causing great damage"]}', '{"prefix":{"text":"dis-","meaning":"bad (不好)"},"root":{"text":"aster","meaning":"star (星)"},"logic":"星象不吉（古人認為災難與凶星有關）。"}', 'natural disaster / disaster relief / disaster management', '[{"en":"The earthquake was a major natural disaster.","zh-TW":"地震是一場重大自然災難。"},{"en":"Disaster relief teams were sent immediately.","zh-TW":"救災隊伍被立即派遣。"}]', '{"adjective":"disastrous"}', NULL, 3, 2058, NULL),
(2059, 'disbursement', '/dɪsˈbɜːrsmənt/', 'noun', '{"zh-TW":["支出；支付"],"en":["the payment of money from a fund"]}', NULL, 'cash disbursement / loan disbursement', '[{"en":"Loan disbursement will occur within 5 days.","zh-TW":"貸款將在5天內撥付。"},{"en":"Track all cash disbursements carefully.","zh-TW":"仔細追蹤所有現金支出。"}]', '{"noun":"disbursement","verb":"disburse"}', NULL, 4, 2059, NULL),
(2060, 'disbursement schedule', '/dɪsˈbɜːrsmənt ˈʃedjuːl/', 'noun', '{"zh-TW":["付款計劃；撥款時間表"],"en":["a plan specifying when and how much money will be paid out"]}', NULL, 'follow the disbursement schedule / approve the disbursement schedule', '[{"en":"The disbursement schedule tied payments to project completion milestones.","zh-TW":"付款計劃將付款與項目完成里程碑相關聯。"},{"en":"The bank required a disbursement schedule before releasing funds.","zh-TW":"銀行在釋放資金前需要付款計劃。"}]', NULL, NULL, 5, 2060, NULL),
(2061, 'discard', '/dɪˈskɑːrd/', 'verb', '{"zh-TW":["丟棄；拋棄"],"en":["to get rid of something no longer useful"]}', NULL, 'discard old files', '[{"en":"Please discard any outdated documents.","zh-TW":"請丟棄任何過時的文件。"},{"en":"The idea was discarded as impractical.","zh-TW":"這個想法因不切實際而被拋棄。"}]', '{"verb":"discard"}', NULL, 3, 2061, NULL),
(2062, 'discern', '/dɪˈsɜːrn/', 'verb', '{"zh-TW":["辨別；識別"],"en":["to recognize or find out with difficulty"]}', NULL, 'discern a pattern / discern the truth / discern nuances', '[{"en":"Experienced researchers can discern subtle patterns in complex data.","zh-TW":"有經驗的研究員可以在複雜數據中辨別出微妙的模式。"},{"en":"It is difficult to discern the author''s true intention from the text alone.","zh-TW":"僅從文字中很難辨別作者的真正意圖。"}]', '{"noun":"discernment","adjective":"discernible"}', NULL, 3, 2062, NULL),
(2063, 'discerning', '/''dɪˈzɜːrnɪŋ/', 'adjective', '{"zh-TW":["有辨別力的；眼光敏銳的"],"en":["having or showing good judgement; able to see differences in quality"]}', NULL, 'discerning customer / discerning investor / discerning eye', '[{"en":"Discerning consumers prefer quality products over cheaply made alternatives.","zh-TW":"有辨別力的消費者偏好高質量產品而非廉價替代品。"},{"en":"A discerning investor looks beyond short-term gains to long-term value.","zh-TW":"眼光敏銳的投資者超越短期利益，著眼於長期價值。"}]', '{"adverb":"discerningly","verb":"discern"}', NULL, 4, 2063, NULL),
(2064, 'discharge', '/dɪsˈtʃɑːrdʒ/', 'noun', '{"zh-TW":["出院；排出"],"en":["the process of releasing a patient from hospital"]}', NULL, 'hospital discharge / discharge date', '[{"en":"The patient was discharged after three days in hospital.","zh-TW":"病患住院三天後出院。"},{"en":"The doctor signed the discharge papers this morning.","zh-TW":"醫生今天早上簽署了出院文件。"}]', '{"verb":"discharge"}', NULL, 3, 2064, 670),
(2065, 'discharge summary', '/dɪsˈtʃɑːrdʒ ˈsʌməri/', 'noun', '{"zh-TW":["出院摘要"],"en":["a document summarizing a patient''s hospital stay"]}', NULL, 'receive a discharge summary / prepare a discharge summary', '[{"en":"The discharge summary outlined the treatment given and follow-up care.","zh-TW":"出院摘要概述了所接受的治療和後續護理。"},{"en":"Keep your discharge summary for future medical consultations.","zh-TW":"請保留出院摘要供未來的醫療諮詢使用。"}]', NULL, NULL, 5, 2065, NULL),
(2066, 'disciplinary', '/ˈdɪsɪplɪneri/', 'adjective', '{"zh-TW":["紀律的；懲戒的"],"en":["relating to punishment or enforcement of rules in a workplace"]}', NULL, 'disciplinary action / disciplinary hearing / disciplinary procedure', '[{"en":"Disciplinary action was taken against the employee.","zh-TW":"對該員工採取了紀律處分。"},{"en":"A formal disciplinary hearing was scheduled for next week.","zh-TW":"正式的紀律聆訊定於下週舉行。"}]', '{"noun":"discipline","verb":"discipline"}', NULL, 4, 2066, NULL),
(2067, 'disciplinary action', '/dɪˈsɪplɪnəri ˈækʃən/', 'noun', '{"zh-TW":["紀律處分"],"en":["formal measures taken by an employer in response to misconduct"]}', NULL, 'take disciplinary action / face disciplinary action / disciplinary action policy', '[{"en":"The manager took disciplinary action after repeated tardiness.","zh-TW":"員工多次遲到後，主管採取了紀律處分。"},{"en":"A written warning is typically the first step in disciplinary action.","zh-TW":"書面警告通常是紀律處分的第一步。"}]', '{"adjective":"disciplinary"}', NULL, 5, 2067, NULL),
(2068, 'discipline', '/ˈdɪsəplɪn/', 'noun / verb', '{"zh-TW":["紀律；學科"],"en":["the practice of training people to obey rules","controlled behavior; a branch of knowledge","a branch of knowledge"]}', '{"root":{"text":"disciple","meaning":"learner (學習者)"},"logic":"學習者應遵守的規範，即「紀律」。"}', 'maintain discipline; self-discipline / academic discipline; self-discipline / academic discipline / maintain discipline', '[{"en":"Good discipline is essential in the workplace.","zh-TW":"良好的紀律在職場是必要的。"},{"en":"Marketing is a rapidly changing discipline.","zh-TW":"行銷是一個快速變化的學科。"},{"en":"Success requires discipline.","zh-TW":"成功需要紀律。"},{"en":"Biology is a scientific discipline.","zh-TW":"生物學是一門科學學科。"},{"en":"Success requires discipline and hard work.","zh-TW":"成功需要紀律和努力。"},{"en":"Psychology is a fascinating discipline.","zh-TW":"心理學是一門迷人的學科。"}]', '{"noun":"discipline","verb":"discipline","adjective":"disciplined"}', NULL, 4, 2068, NULL),
(2069, 'disclaimer', '/dɪsˈkleɪmər/', 'noun', '{"zh-TW":["免責聲明"],"en":["a statement denying responsibility for something"]}', NULL, 'include a disclaimer / legal disclaimer', '[{"en":"The report includes a disclaimer about the accuracy of predictions.","zh-TW":"報告包含關於預測準確性的免責聲明。"},{"en":"All marketing materials must include the required legal disclaimer.","zh-TW":"所有行銷材料必須包含所需的法律免責聲明。"}]', '{"verb":"disclaim"}', NULL, 4, 2069, NULL),
(2070, 'disclose', '/dɪˈskloʊz/', 'verb', '{"zh-TW":["揭露；公開"],"en":["to make information known publicly"]}', NULL, 'disclose information', '[{"en":"The company refused to disclose its financial data.","zh-TW":"公司拒絕公開其財務數據。"},{"en":"He disclosed the details of the agreement.","zh-TW":"他揭露了協議的細節。"}]', '{"noun":"disclosure","verb":"disclose"}', NULL, 3, 2070, 671),
(2071, 'disclosure policy', '/dɪˈskloʊʒər ˈpɒlɪsi/', 'noun', '{"zh-TW":["披露政策"],"en":["rules governing what information must be disclosed and when"]}', NULL, 'implement disclosure policy / comply with disclosure policy', '[{"en":"The listed company updated its disclosure policy after new regulations.","zh-TW":"上市公司在新法規後更新了其披露政策。"},{"en":"A clear disclosure policy builds investor confidence.","zh-TW":"清晰的披露政策建立了投資者信心。"}]', NULL, NULL, 5, 2071, NULL),
(2072, 'disclosure requirement', '/dɪsˈkloʊʒər rɪˈkwaɪərmənt/', 'noun', '{"zh-TW":["披露要求"],"en":["a legal obligation to provide specific information to stakeholders or regulators"]}', NULL, 'meet disclosure requirements / disclosure requirement compliance', '[{"en":"Listed companies must comply with all disclosure requirements.","zh-TW":"上市公司必須遵守所有披露要求。"},{"en":"Failure to meet disclosure requirements can result in delisting.","zh-TW":"未能滿足披露要求可能導致摘牌。"}]', NULL, NULL, 5, 2072, NULL),
(2073, 'disclosure requirements', '/dɪsˈkloʊʒər rɪˈkwaɪərmənt/', 'noun', '{"zh-TW":["披露要求"],"en":["regulations requiring companies to publish certain information publicly"]}', NULL, 'meet disclosure requirements / comply with disclosure requirements', '[{"en":"Listed companies must comply with all disclosure requirements.","zh-TW":"上市公司必須遵守所有披露要求。"},{"en":"Failure to meet disclosure requirements can result in regulatory action.","zh-TW":"未能滿足披露要求可能導致監管行動。"}]', NULL, NULL, 5, 2073, NULL),
(2074, 'disclosure statement', '/dɪˈskloʊʒər ˈsteɪtmənt/', 'noun', '{"zh-TW":["披露聲明"],"en":["a formal document providing required information to stakeholders"]}', NULL, 'issue a disclosure statement / review the disclosure statement', '[{"en":"The company issued a disclosure statement before the public offering.","zh-TW":"公司在公開發行前發出了披露聲明。"},{"en":"Investors rely on the disclosure statement to make informed decisions.","zh-TW":"投資者依靠披露聲明做出明智的決策。"}]', NULL, NULL, 5, 2074, NULL),
(2075, 'discount', '/ˈdɪskaʊnt/', 'noun / verb', '{"zh-TW":["折扣；打折"],"en":["a reduction in the usual price"]}', NULL, 'offer/give a discount', '[{"en":"We offer a 20% discount for bulk orders.","zh-TW":"我們對大量訂單提供八折優惠。"},{"en":"The store discounted all winter items.","zh-TW":"商店對所有冬季商品打折。"}]', '{"noun":"discount","verb":"discount","adjective":"discounted"}', NULL, 3, 2075, 105),
(2076, 'discount rate', '/ˈdɪskaʊnt reɪt/', 'noun', '{"zh-TW":["折現率；貼現率"],"en":["the interest rate used to determine present value of future cash flows"]}', NULL, 'set the discount rate / apply a discount rate', '[{"en":"A higher discount rate reduces the present value of future earnings.","zh-TW":"較高的折現率降低了未來收益的現值。"},{"en":"The discount rate reflects the risk associated with the investment.","zh-TW":"折現率反映了與投資相關的風險。"}]', NULL, NULL, 5, 2076, NULL),
(2077, 'discount to net asset value', '/ˈdɪskaʊnt tə net ˈæset ˈvæljuː/', 'noun', '{"zh-TW":["折讓；以低於淨資產值的折扣交易"],"en":["the percentage by which a fund or company trades below its asset value"]}', NULL, 'trade at a discount to net asset value / reduce the discount to net asset value', '[{"en":"Closed-end funds often trade at a discount to net asset value.","zh-TW":"封閉式基金通常以低於淨資產值的折讓交易。"},{"en":"Activist investors target companies trading at a significant discount to net asset value.","zh-TW":"激進投資者針對以顯著折讓於淨資產值交易的公司。"}]', NULL, NULL, 5, 2077, NULL),
(2078, 'discounted cash flow', '/dɪˈskaʊntɪd kæʃ floʊ/', 'noun', '{"zh-TW":["折現現金流"],"en":["a valuation method estimating the value of an investment based on future cash flows"]}', NULL, 'apply discounted cash flow analysis / discounted cash flow model', '[{"en":"Discounted cash flow analysis values the company at $20 million.","zh-TW":"折現現金流分析將公司估值為2000萬元。"},{"en":"Discounted cash flow is the most rigorous method for investment appraisal.","zh-TW":"折現現金流是投資評估最嚴格的方法。"}]', '{"abbreviation":"DCF"}', NULL, 5, 2078, NULL),
(2079, 'discourse', '/ˈdɪskɔːrs/', 'noun', '{"zh-TW":["論述；話語"],"en":["written or spoken communication or debate"]}', NULL, 'academic discourse / political discourse / enter the discourse', '[{"en":"The conference opened up a new discourse around digital privacy.","zh-TW":"會議開啟了關於數字隱私的新論述。"},{"en":"Critical thinkers shape public discourse on important social issues.","zh-TW":"批判性思考者塑造了重要社會問題的公眾話語。"}]', '{"verb":"discourse","adjective":"discursive"}', NULL, 3, 2079, NULL),
(2080, 'discourse analysis', '/ˈdɪskɔːrs əˈnæləsɪs/', 'noun', '{"zh-TW":["話語分析"],"en":["the study of language used in texts and contexts to understand power and meaning"]}', NULL, 'conduct discourse analysis / critical discourse analysis / discourse analysis methodology', '[{"en":"Critical discourse analysis reveals how media language constructs social reality.","zh-TW":"批判性話語分析揭示了媒體語言如何建構社會現實。"},{"en":"Discourse analysis is widely used in sociology, linguistics, and political science.","zh-TW":"話語分析在社會學、語言學和政治科學中被廣泛使用。"}]', NULL, NULL, 5, 2080, NULL),
(2081, 'discover', '/dɪˈskʌvər/', 'verb', '{"zh-TW":["發現"],"en":["to find something for the first time"]}', NULL, 'discover a solution; discover a new species / discover the truth', '[{"en":"Scientists discovered a new treatment.","zh-TW":"科學家發現了一種新療法。"},{"en":"She discovered an error in the report.","zh-TW":"她在報告中發現了一個錯誤。"},{"en":"Columbus discovered America in 1492.","zh-TW":"哥倫布在1492年發現了美洲。"},{"en":"She discovered the truth about her past.","zh-TW":"她發現了關於她過去的真相。"}]', '{"noun":"discovery","verb":"discover"}', NULL, 3, 2081, NULL),
(2082, 'discovery', '/dɪˈskʌvəri/', 'noun', '{"zh-TW":["訴訟前調查；事實揭露"],"en":["the pre-trial phase in which parties obtain evidence from each other"]}', NULL, 'discovery process / electronic discovery / discovery request', '[{"en":"Discovery allows both parties to review relevant documents before trial.","zh-TW":"訴訟前調查允許雙方在審判前審閱相關文件。"},{"en":"The company failed to comply with the discovery requests.","zh-TW":"公司未能遵守事實揭露要求。"}]', NULL, NULL, 3, 2082, NULL),
(2083, 'discrepancy', '/dɪˈskrepənsi/', 'noun', '{"zh-TW":["差異；不一致"],"en":["a lack of agreement between two or more facts or claims"]}', NULL, 'financial discrepancy / discrepancy in the records / resolve a discrepancy', '[{"en":"A discrepancy was found between the invoice and the purchase order.","zh-TW":"發票和採購訂單之間發現了差異。"},{"en":"The auditor flagged a discrepancy in the accounts receivable balance.","zh-TW":"審計師標記了應收帳款餘額中的差異。"}]', '{"adjective":"discrepant","plural":"discrepancies"}', NULL, 4, 2083, NULL),
(2084, 'discretion', '/dɪˈskreʃən/', 'noun', '{"zh-TW":["判斷力；酌情權"],"en":["the freedom to decide what should be done"]}', NULL, 'at one''s discretion', '[{"en":"Use your own discretion when handling complaints.","zh-TW":"處理投訴時請自行判斷。"},{"en":"Bonuses are awarded at management''s discretion.","zh-TW":"獎金由管理層酌情發放。"}]', '{"noun":"discretion","adjective":"discreet/discretionary"}', NULL, 4, 2084, 550),
(2085, 'discretionary spending', '/dɪˈskreʃəneri ˈspendɪŋ/', 'noun', '{"zh-TW":["可裁量支出；選擇性消費"],"en":["non-essential spending that can be cut during budget constraints"]}', NULL, 'reduce discretionary spending / discretionary spending cuts', '[{"en":"The company reduced discretionary spending to preserve cash.","zh-TW":"公司削減了可裁量支出以保存現金。"},{"en":"Consumers tend to cut discretionary spending during recessions.","zh-TW":"消費者在經濟衰退期間傾向於削減可裁量支出。"}]', NULL, NULL, 5, 2085, NULL),
(2086, 'discriminate', '/dɪˈskrɪmɪneɪt/', 'verb', '{"zh-TW":["歧視；區別"],"en":["to treat unfairly based on prejudice"]}', NULL, 'discriminate against', '[{"en":"It is illegal to discriminate against employees based on age.","zh-TW":"基於年齡歧視員工是違法的。"},{"en":"Can you discriminate between the two options?","zh-TW":"你能區分這兩個選項嗎？"}]', '{"noun":"discrimination","verb":"discriminate","adjective":"discriminatory"}', NULL, 4, 2086, NULL),
(2087, 'discrimination', '/dɪˌskrɪmɪˈneɪʃn/', 'noun', '{"zh-TW":["歧視；辨別"],"en":["unjust treatment based on race, age, or gender"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"crimin","meaning":"separate (區分)"},"suffix":{"text":"-ation","meaning":"act of (行為)"},"logic":"把人分開區別對待，即「歧視」。"}', 'racial discrimination / gender discrimination', '[{"en":"Discrimination based on age is illegal.","zh-TW":"年齡歧視是違法的。"},{"en":"The company has a strict anti-discrimination policy.","zh-TW":"公司有嚴格的反歧視政策。"}]', '{"verb":"discriminate","adjective":"discriminatory"}', NULL, 5, 2087, NULL),
(2088, 'discursive', '/dɪˈskɜːrsɪv/', 'adjective', '{"zh-TW":["論述的；說理的"],"en":["relating to discourse; dealing with various topics in a lengthy way"]}', NULL, 'discursive analysis / discursive style / discursive essay', '[{"en":"The author''s discursive style covers many themes in depth.","zh-TW":"作者的論述風格深入涵蓋了許多主題。"},{"en":"Discursive analysis examines how language constructs social reality.","zh-TW":"論述分析研究語言如何建構社會現實。"}]', '{"noun":"discourse","adverb":"discursively"}', NULL, 4, 2088, NULL),
(2089, 'discuss', '/dɪˈskʌs/', 'verb', '{"zh-TW":["討論"],"en":["to talk about something in detail","to talk about something with others"]}', NULL, 'discuss the matter/issue; discuss a topic / discuss the matter', '[{"en":"We need to discuss the budget proposal.","zh-TW":"我們需要討論預算提案。"},{"en":"The team discussed several options.","zh-TW":"團隊討論了幾個方案。"},{"en":"Let''s discuss this later.","zh-TW":"我們稍後再討論這件事。"},{"en":"They discussed the proposal at the meeting.","zh-TW":"他們在會議上討論了提案。"}]', '{"noun":"discussion","verb":"discuss"}', NULL, 3, 2089, 106),
(2090, 'discussion', 'dɪˈskʌʃən', 'noun', '{"zh-TW":["討論；商議","辯論"],"en":["a conversation about something","an examination of issues"]}', NULL, 'open discussion/group discussion', '[{"en":"The manager encouraged open discussion.","zh-TW":"經理鼓勵開放的討論。"}]', '{"verb":"discuss","adjective":"discussable"}', NULL, 4, 2090, NULL),
(2091, 'disembark', '/ˌdɪsɪmˈbɑːrk/', 'verb', '{"zh-TW":["下船；下機"],"en":["to leave a ship or aircraft"]}', NULL, 'disembark passengers / disembark at the port', '[{"en":"Passengers were asked to disembark in an orderly manner.","zh-TW":"乘客被要求有秩序地下船。"},{"en":"We disembarked at the port of call.","zh-TW":"我們在停靠港口下船。"}]', '{"noun":"disembarkation"}', NULL, 3, 2091, NULL),
(2092, 'disenfranchisement', '/ˌdɪsɪnˈfræntʃaɪzmənt/', 'noun', '{"zh-TW":["剝奪公民權；剝奪選舉權"],"en":["the state of being deprived of rights, especially voting rights"]}', NULL, 'voter disenfranchisement / challenge disenfranchisement / prevent disenfranchisement', '[{"en":"Strict ID laws have been criticized as a form of voter disenfranchisement.","zh-TW":"嚴格的身份證法律被批評為一種選民剝奪公民權的形式。"},{"en":"Disenfranchisement of prisoners is debated across democracies.","zh-TW":"監獄犯人的選舉權剝奪在各民主國家引發辯論。"}]', '{"verb":"disenfranchise","adjective":"disenfranchised"}', NULL, 5, 2092, NULL),
(2093, 'dish', '/dɪʃ/', 'noun', '{"zh-TW":["菜餚；碗盤"],"en":["a type of food prepared in a particular way"]}', NULL, 'signature dish / main dish', '[{"en":"The chef''s signature dish is the braised short rib.","zh-TW":"主廚的招牌菜是紅燒牛小排。"},{"en":"Each dish is made from locally sourced ingredients.","zh-TW":"每道菜餚都使用當地採購的食材製作。"}]', NULL, NULL, 1, 2093, NULL),
(2094, 'disinflation', '/ˌdɪsɪnˈfleɪʃən/', 'noun', '{"zh-TW":["通膨趨緩"],"en":["a reduction in the rate of inflation, as opposed to deflation"]}', NULL, 'period of disinflation / disinflation policy / gradual disinflation', '[{"en":"The central bank achieved disinflation by raising interest rates over two years.","zh-TW":"中央銀行通過兩年來提高利率實現了通膨趨緩。"},{"en":"Disinflation is typically less damaging to the economy than deflation.","zh-TW":"通膨趨緩對經濟的損害通常低於通貨緊縮。"}]', '{"adjective":"disinflationary"}', NULL, 4, 2094, NULL),
(2095, 'disinformation', '/dɪsˌɪnfəˈmeɪʃən/', 'noun', '{"zh-TW":["虛假資訊；不實消息（故意散布）"],"en":["deliberately false information spread to deceive"]}', NULL, 'spread disinformation / combat disinformation / disinformation campaign', '[{"en":"A coordinated disinformation campaign undermined public trust in vaccines.","zh-TW":"一場有組織的虛假資訊宣傳破壞了公眾對疫苗的信任。"},{"en":"Researchers study how disinformation spreads on social platforms.","zh-TW":"研究人員研究虛假資訊如何在社交平台上傳播。"}]', '{"adjective":"disinformation"}', NULL, 5, 2095, NULL),
(2096, 'dismiss', '/dɪˈsmɪs/', 'verb', '{"zh-TW":["解僱；駁回","解僱；駁回；不理會"],"en":["to remove from a job; to reject","to send away","to refuse to consider"]}', '{"prefix":{"text":"dis-","meaning":"away (離開)"},"root":{"text":"miss","meaning":"send (送)"},"logic":"把人送走，即「解僱」或「不理會」。"}', 'dismiss an employee/idea; dismiss an employee / dismiss the idea / dismiss the case', '[{"en":"He was dismissed for misconduct.","zh-TW":"他因行為不當被解僱。"},{"en":"The court dismissed the case.","zh-TW":"法院駁回了此案。"},{"en":"The manager dismissed the complaint.","zh-TW":"經理駁回了投訴。"},{"en":"You shouldn''t dismiss his suggestions so quickly.","zh-TW":"你不應該這麼快就否定他的建議。"}]', '{"noun":"dismissal","verb":"dismiss"}', NULL, 3, 2096, NULL),
(2097, 'dismissal', '/dɪsˈmɪsəl/', 'noun', '{"zh-TW":["解僱；免職"],"en":["the act of terminating someone''s employment"]}', NULL, 'wrongful dismissal / dismissal procedure', '[{"en":"The dismissal was considered unfair by the labor board.","zh-TW":"解僱被勞動委員會認定為不公平。"},{"en":"All dismissals must follow the company''s formal procedures.","zh-TW":"所有解僱必須遵循公司的正式程序。"}]', '{"verb":"dismiss","adjective":"dismissed"}', NULL, 3, 2097, NULL),
(2098, 'dismissal notice', '/dɪsˈmɪsəl ˈnoʊtɪs/', 'noun', '{"zh-TW":["解雇通知"],"en":["a formal written notice informing an employee of their termination"]}', NULL, 'serve a dismissal notice / receive a dismissal notice', '[{"en":"The employee received a dismissal notice effective immediately.","zh-TW":"員工收到了即時生效的解雇通知。"},{"en":"A dismissal notice must specify the reason for termination.","zh-TW":"解雇通知必須說明解雇原因。"}]', NULL, NULL, 5, 2098, NULL),
(2099, 'disorder', '/dɪsˈɔːrdər/', 'noun', '{"zh-TW":["失調；混亂"],"en":["a state of confusion","a medical condition"]}', '{"prefix":{"text":"dis-","meaning":"not (不)"},"root":{"text":"order","meaning":"order (秩序)"},"logic":"沒有秩序，即「混亂」。"}', 'mental disorder / eating disorder / in disorder', '[{"en":"The room was in complete disorder.","zh-TW":"房間完全一片混亂。"},{"en":"She was diagnosed with an anxiety disorder.","zh-TW":"她被診斷出焦慮症。"}]', '{"adjective":"disordered","adjective2":"disorderly"}', NULL, 3, 2099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2100, 'disparate', '/''dɪspərɪt/', 'adjective', '{"zh-TW":["迥異的；截然不同的"],"en":["essentially different in kind; not allowing comparison; made up of fundamentally different elements"]}', NULL, 'disparate views / disparate groups / disparate data', '[{"en":"The committee brought together experts from disparate fields to address the complex issue.","zh-TW":"委員會匯集了來自不同領域的專家，以解決這個複雜問題。"},{"en":"Combining disparate data sources can be challenging but yields comprehensive insights.","zh-TW":"結合截然不同的數據來源可能具有挑戰性，但能產生全面的見解。"}]', '{"adverb":"disparately","noun":"disparity"}', NULL, 3, 2100, NULL),
(2101, 'disparity', '/dɪˈspærɪti/', 'noun', '{"zh-TW":["差距；懸殊"],"en":["a great difference or inequality between groups or figures"]}', NULL, 'income disparity / pay disparity / reduce disparity', '[{"en":"A significant pay disparity was identified between junior and senior staff.","zh-TW":"在初級和高級員工之間識別了顯著的薪資差距。"},{"en":"The report highlighted regional disparities in economic growth.","zh-TW":"報告強調了經濟增長的地區差距。"}]', '{"adjective":"disparate","adverb":"disparately"}', NULL, 3, 2101, NULL),
(2102, 'dispatch', '/dɪˈspætʃ/', 'verb / noun', '{"zh-TW":["派遣；發送"],"en":["to send off to a destination"]}', NULL, 'dispatch goods/a team', '[{"en":"The order was dispatched this morning.","zh-TW":"訂單今早已發出。"},{"en":"A repair team was dispatched immediately.","zh-TW":"維修團隊立即被派遣。"}]', '{"noun":"dispatch","verb":"dispatch"}', NULL, 3, 2102, NULL),
(2103, 'displace', '/''dɪsˈpleɪs/', 'verb', '{"zh-TW":["取代；移置；迫使遷離"],"en":["to take the place of something or force someone or something from their usual place"]}', NULL, 'displace workers / displace traditional methods / displace residents', '[{"en":"Automation has displaced thousands of manufacturing workers in recent years.","zh-TW":"近年來，自動化取代了數千名製造業工人。"},{"en":"The flood displaced hundreds of families from their homes.","zh-TW":"洪水迫使數百個家庭離開了他們的家園。"}]', '{"noun":"displacement"}', NULL, 3, 2103, NULL),
(2104, 'display', '/dɪˈspleɪ/', 'verb / noun', '{"zh-TW":["展示；顯示","展示；陳列"],"en":["to show something publicly","an arrangement of items for public viewing"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"play","meaning":"fold (展開)"},"logic":"展開來讓人看，即「展示」。"}', 'on display; on display / window display', '[{"en":"The products are displayed in the window.","zh-TW":"產品展示在櫥窗中。"},{"en":"The artwork is on display until March.","zh-TW":"藝術品展出至三月。"},{"en":"The new products are on display in the window.","zh-TW":"新產品正在櫥窗展示。"},{"en":"The museum has an impressive display of artifacts.","zh-TW":"博物館有令人印象深刻的文物展示。"}]', '{"noun":"display","verb":"display"}', NULL, 3, 2104, NULL),
(2105, 'disposable income', '/dɪˈspəʊzəbəl ˈɪnkʌm/', 'noun', '{"zh-TW":["可支配收入"],"en":["the amount of income left after deducting taxes, available for spending or saving"]}', NULL, 'increase disposable income / disposable income growth / consumer disposable income', '[{"en":"Rising disposable income boosted retail spending across all consumer categories.","zh-TW":"可支配收入的增加促進了所有消費類別的零售支出。"},{"en":"Low disposable income households are more vulnerable to economic shocks.","zh-TW":"可支配收入低的家庭更容易受到經濟衝擊的影響。"}]', NULL, NULL, 5, 2105, NULL),
(2106, 'disposal', '/dɪˈspoʊzl/', 'noun', '{"zh-TW":["處理；處置"],"en":["the act of getting rid of something"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"pos","meaning":"put (放置)"},"suffix":{"text":"-al","meaning":"act of (行為)"},"logic":"把東西放到一邊去，即「處置」。"}', 'waste disposal / at one''s disposal', '[{"en":"Proper waste disposal protects the environment.","zh-TW":"適當的廢物處理保護環境。"},{"en":"I am at your disposal.","zh-TW":"我隨時為您效勞。"}]', '{"verb":"dispose","adjective":"disposable"}', NULL, 3, 2106, NULL),
(2107, 'disposal value', '/dɪˈspoʊzəl ˈvæljuː/', 'noun', '{"zh-TW":["處置價值；殘值"],"en":["the estimated value of an asset at the end of its useful life"]}', NULL, 'calculate disposal value / residual disposal value', '[{"en":"The disposal value of the equipment was estimated at 10% of cost.","zh-TW":"設備的處置價值估計為成本的10%。"},{"en":"Assets with a disposal value above zero are sold, not scrapped.","zh-TW":"處置價值高於零的資產被出售，而非報廢。"}]', '{"synonym":"residual value","synonym2":"salvage value"}', NULL, 5, 2107, NULL),
(2108, 'dispose', '/dɪˈspoʊz/', 'verb', '{"zh-TW":["處理；丟棄"],"en":["to get rid of; to arrange"]}', NULL, 'dispose of waste', '[{"en":"Please dispose of waste properly.","zh-TW":"請正確處理廢棄物。"},{"en":"The company disposed of its old equipment.","zh-TW":"公司處理了舊設備。"}]', '{"noun":"disposal/disposition","verb":"dispose","adjective":"disposable"}', NULL, 3, 2108, 336),
(2109, 'disproportionate', '/''dɪsprəˌpɔːrʃənɪt/', 'adjective', '{"zh-TW":["不成比例的；過分的"],"en":["too large or too small in comparison with something else; out of proportion"]}', NULL, 'disproportionate response / disproportionate impact / disproportionate cost', '[{"en":"The disproportionate cost of the project made it financially unviable.","zh-TW":"項目不成比例的成本使其在財務上不可行。"},{"en":"The policy had a disproportionate impact on low-income families.","zh-TW":"該政策對低收入家庭造成了不成比例的影響。"}]', '{"adverb":"disproportionately","noun":"disproportion"}', NULL, 5, 2109, NULL),
(2110, 'dispute', '/dɪˈspjuːt/', 'noun / verb', '{"zh-TW":["爭議；爭論","爭議；糾紛"],"en":["a disagreement or argument"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"pute","meaning":"think (思考)"},"logic":"想法分歧，即「爭議」。"}', 'resolve/settle a dispute; legal dispute / labor dispute / settle a dispute', '[{"en":"The dispute was settled out of court.","zh-TW":"爭議在庭外解決了。"},{"en":"They disputed the accuracy of the report.","zh-TW":"他們對報告的準確性提出異議。"},{"en":"The labor dispute lasted several weeks.","zh-TW":"勞資糾紛持續了好幾週。"},{"en":"They settled the dispute out of court.","zh-TW":"他們在庭外解決了糾紛。"}]', '{"noun":"dispute","verb":"dispute"}', NULL, 3, 2110, NULL),
(2111, 'dispute resolution', '/dɪˈspjuːt ˌrɛzəˈluːʃən/', 'noun', '{"zh-TW":["爭議解決；糾紛解決"],"en":["the methods used to settle disagreements"]}', NULL, 'alternative dispute resolution / dispute resolution process', '[{"en":"The contract includes a clause for alternative dispute resolution.","zh-TW":"合約包含替代性爭議解決條款。"},{"en":"Mediation is a common method of dispute resolution in business.","zh-TW":"調解是商業中常見的爭議解決方法。"}]', NULL, NULL, 5, 2111, NULL),
(2112, 'dispute resolution mechanism', '/dɪˈspjuːt ˌrezəˈluːʃən ˈmekənɪzəm/', 'noun', '{"zh-TW":["爭議解決機制"],"en":["a formal process for resolving disagreements between parties"]}', NULL, 'establish a dispute resolution mechanism / use a dispute resolution mechanism', '[{"en":"The contract includes a clear dispute resolution mechanism.","zh-TW":"合約包含明確的爭議解決機制。"},{"en":"Mediation is the preferred dispute resolution mechanism for commercial disputes.","zh-TW":"調解是商業糾紛的首選爭議解決機制。"}]', NULL, NULL, 5, 2112, NULL),
(2113, 'dispute settlement', '/dɪˈspjuːt ˈsetlmənt/', 'noun', '{"zh-TW":["爭議解決；糾紛解決"],"en":["the resolution of a conflict or disagreement through negotiation or legal process"]}', NULL, 'reach a dispute settlement / dispute settlement procedure', '[{"en":"The two companies reached a dispute settlement without proceeding to litigation.","zh-TW":"兩家公司在不進行訴訟的情況下達成了爭議解決。"},{"en":"Dispute settlement through mediation is faster and less costly than arbitration.","zh-TW":"通過調解進行爭議解決比仲裁更快且成本更低。"}]', NULL, NULL, 5, 2113, NULL),
(2114, 'disrupt', '/dɪsˈrʌpt/', 'verb', '{"zh-TW":["擾亂；中斷"],"en":["to interrupt the normal course of"]}', NULL, 'disrupt operations/services', '[{"en":"The strike disrupted public transportation.","zh-TW":"罷工擾亂了公共交通。"},{"en":"New technology is disrupting traditional industries.","zh-TW":"新技術正在顛覆傳統產業。"}]', '{"noun":"disruption","verb":"disrupt","adjective":"disruptive"}', NULL, 3, 2114, NULL),
(2115, 'disruption', '/dɪˈsrʌpʃən/', 'noun', '{"zh-TW":["顛覆；中斷"],"en":["a radical change that displaces an established market or product"]}', NULL, 'disruptive technology / market disruption / supply chain disruption', '[{"en":"The digital disruption of retail forced many stores to close.","zh-TW":"零售業的數位顛覆迫使許多商店關閉。"},{"en":"Startups thrive by creating disruption in established industries.","zh-TW":"新創公司通過在既有行業中創造顛覆而蓬勃發展。"}]', '{"verb":"disrupt","adjective":"disruptive","noun":"disruptor"}', NULL, 4, 2115, NULL),
(2116, 'disruptive', '/''dɪsˌrʌptɪv/', 'adjective', '{"zh-TW":["破壞性的；顛覆性的；干擾性的"],"en":["causing or tending to cause disruption; innovative in a way that causes change"]}', NULL, 'disruptive technology / disruptive force / disruptive change', '[{"en":"Artificial intelligence is a disruptive technology reshaping the global economy.","zh-TW":"人工智慧是重塑全球經濟的破壞性技術。"},{"en":"The company embraced disruptive change rather than resist it.","zh-TW":"公司擁抱破壞性變化而不是抵制它。"}]', '{"adverb":"disruptively","noun":"disruption"}', NULL, 4, 2116, NULL),
(2117, 'disruptive innovation', '/dɪsˈrʌptɪv ˌɪnəˈveɪʃən/', 'noun', '{"zh-TW":["顛覆性創新"],"en":["an innovation that creates a new market and disrupts an existing one"]}', NULL, 'embrace disruptive innovation / resist disruptive innovation / impact of disruptive innovation', '[{"en":"Streaming services were a disruptive innovation that transformed entertainment.","zh-TW":"串流服務是一種顛覆性創新，改變了娛樂業。"},{"en":"Disruptive innovation often comes from startups rather than established firms.","zh-TW":"顛覆性創新通常來自初創公司而非老牌企業。"}]', '{"adjective":"disruptive","verb":"disrupt"}', NULL, 5, 2117, NULL),
(2118, 'disruptive technology', '/''dɪˌsrʌptɪv tekˌnɒlədʒi/', 'noun', '{"zh-TW":["顛覆性技術"],"en":["an innovation that significantly alters or displaces an established market or technology"]}', NULL, 'develop disruptive technology / impact of disruptive technology / embrace disruptive technology', '[{"en":"The smartphone was a disruptive technology that transformed multiple industries simultaneously.","zh-TW":"智能手機是一種顛覆性技術，同時改變了多個行業。"},{"en":"Established companies must be willing to cannibalize their own products when disruptive technology emerges.","zh-TW":"當顛覆性技術出現時，成熟企業必須願意以自身產品相互競爭。"}]', '{"verb":"disrupt","noun":"disruption","adjective":"disruptive"}', NULL, 5, 2118, NULL),
(2119, 'disseminate', '/dɪˈsemɪneɪt/', 'verb', '{"zh-TW":["傳播；散佈（資訊）"],"en":["to spread or distribute information widely"]}', NULL, 'disseminate information / disseminate research / widely disseminated', '[{"en":"The organization disseminates findings through public reports.","zh-TW":"該組織透過公開報告傳播研究成果。"},{"en":"Social media helps disseminate news rapidly.","zh-TW":"社交媒體有助於快速傳播新聞。"}]', '{"noun":"dissemination","adjective":"disseminated"}', NULL, 4, 2119, NULL),
(2120, 'dissemination', '/dɪˌsemɪˈneɪʃən/', 'noun', '{"zh-TW":["傳播；散佈"],"en":["the act of spreading information, knowledge, or opinions widely"]}', NULL, 'information dissemination / dissemination of research / dissemination strategy', '[{"en":"The dissemination of accurate health information was crucial during the pandemic.","zh-TW":"在疫情期間，準確健康信息的傳播至關重要。"},{"en":"Research findings must be published for their dissemination to the scientific community.","zh-TW":"研究結果必須發表，才能向科學界傳播。"}]', '{"verb":"disseminate","adjective":"disseminated"}', NULL, 5, 2120, NULL),
(2121, 'dissent', '/''dɪˌsent/', 'noun', '{"zh-TW":["異議；不同意見"],"en":["the holding or expression of opinions at variance with those held by authority"]}', NULL, 'voice dissent / political dissent / dissent from', '[{"en":"The policy was passed despite strong dissent from several committee members.","zh-TW":"儘管幾位委員會成員強烈反對，該政策仍獲得通過。"},{"en":"Her willingness to express dissent made her a respected voice in the organization.","zh-TW":"她願意表達異議使她成為組織中受人尊重的聲音。"}]', '{"verb":"dissent","adjective":"dissenting","noun2":"dissenter"}', NULL, 3, 2121, NULL),
(2122, 'dissertation', '/ˌdɪsərˈteɪʃən/', 'noun', '{"zh-TW":["論文；學位論文"],"en":["a long essay on a subject for a university degree"]}', NULL, 'doctoral dissertation / write a dissertation', '[{"en":"She wrote her dissertation on market behavior.","zh-TW":"她的論文主題是市場行為。"},{"en":"His dissertation was published as a book.","zh-TW":"他的論文出版成書了。"}]', '{"noun":"dissertation"}', NULL, 4, 2122, NULL),
(2123, 'dissolution', '/ˌdɪsəˈluːʃən/', 'noun', '{"zh-TW":["解散；解體"],"en":["the action of formally closing down or ending an organization"]}', NULL, 'dissolution of parliament / dissolution of a company / dissolution of a partnership', '[{"en":"The dissolution of the company left employees without severance pay.","zh-TW":"公司解散使員工沒有遣散費。"},{"en":"Parliament was dissolved ahead of the early election.","zh-TW":"議會在提前選舉之前解散了。"}]', '{"verb":"dissolve","adjective":"dissolved"}', NULL, 4, 2123, NULL),
(2124, 'dissolve', '/dɪˈzɑːlv/', 'verb', '{"zh-TW":["解散；溶解"],"en":["to officially end; to mix into a liquid"]}', NULL, 'dissolve a partnership', '[{"en":"The partnership was dissolved last year.","zh-TW":"合夥關係去年解散了。"},{"en":"Sugar dissolves in water.","zh-TW":"糖溶解在水中。"}]', '{"noun":"dissolution","verb":"dissolve"}', NULL, 3, 2124, NULL),
(2125, 'dissonance', '/ˈdɪsənəns/', 'noun', '{"zh-TW":["不協調；不一致"],"en":["lack of harmony among components; inconsistency"]}', NULL, 'cognitive dissonance / moral dissonance / create dissonance', '[{"en":"There is clear dissonance between the stated values and actual behavior.","zh-TW":"陳述的價值觀與實際行為之間存在明顯的不協調。"},{"en":"The dissonance between theory and data requires re-examination of assumptions.","zh-TW":"理論與數據之間的不一致需要重新審視假設。"}]', '{"adjective":"dissonant","adverb":"dissonantly"}', NULL, 4, 2125, NULL),
(2126, 'distance', '/ˈdɪstəns/', 'noun', '{"zh-TW":["距離"],"en":["the space between two points"]}', NULL, 'long distance / keep one''s distance', '[{"en":"What''s the distance to the airport?","zh-TW":"到機場有多遠？"},{"en":"Keep your distance from the edge.","zh-TW":"離邊緣遠一點。"}]', '{"adjective":"distant"}', NULL, 3, 2126, NULL),
(2127, 'distance learning', '/ˈdɪstəns ˈlɜːrnɪŋ/', 'noun', '{"zh-TW":["遠距學習；函授"],"en":["education where students and teachers are in different locations"]}', NULL, 'enroll in distance learning / distance learning course', '[{"en":"Distance learning allows students to study at their own pace.","zh-TW":"遠距學習允許學生按自己的步調學習。"},{"en":"She completed her degree through distance learning while working.","zh-TW":"她在工作的同時透過遠距學習完成了學位。"}]', NULL, NULL, 5, 2127, NULL),
(2128, 'distinct', '/dɪˈstɪŋkt/', 'adjective', '{"zh-TW":["明顯的；不同的","不同的；明顯的"],"en":["clearly different or separate"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"tinct","meaning":"prick/mark (刺/標記)"},"logic":"被標記而分開的，即「不同的」。"}', 'distinct advantage/difference; distinct difference / distinct advantage / distinct from', '[{"en":"There is a distinct difference between the two.","zh-TW":"兩者之間有明顯的區別。"},{"en":"The product has a distinct advantage.","zh-TW":"該產品有明顯的優勢。"},{"en":"The two species are distinct from each other.","zh-TW":"這兩個物種彼此不同。"},{"en":"There is a distinct possibility of rain.","zh-TW":"有明顯下雨的可能性。"}]', '{"noun":"distinction","adjective":"distinct/distinctive","adverb":"distinctly"}', NULL, 3, 2128, NULL),
(2129, 'distinguish', '/dɪˈstɪŋɡwɪʃ/', 'verb', '{"zh-TW":["區分；辨別"],"en":["to recognize differences between things"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"sting","meaning":"prick/mark (刺/標記)"},"suffix":{"text":"-uish","meaning":"make (使)"},"logic":"使標記分開，即「區分」。"}', 'distinguish between/from; distinguish between / distinguish oneself', '[{"en":"It''s hard to distinguish the original from the copy.","zh-TW":"很難區分原件和副本。"},{"en":"What distinguishes our brand from competitors?","zh-TW":"什麼使我們的品牌與競爭對手不同？"},{"en":"It is important to distinguish fact from opinion.","zh-TW":"區分事實和意見很重要。"},{"en":"She distinguished herself in her field.","zh-TW":"她在自己的領域中出類拔萃。"}]', '{"adjective":"distinguished","verb":"distinguish","adjective2":"distinguishable"}', NULL, 4, 2129, NULL),
(2130, 'distribute', '/dɪˈstrɪbjuːt/', 'verb', '{"zh-TW":["分配；分發"],"en":["to give shares of something to several people"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"tribute","meaning":"assign (分派)"},"logic":"分開指派給各人，即「分配」。"}', 'distribute evenly/widely; distribute evenly / distribute resources', '[{"en":"The company distributes products worldwide.","zh-TW":"公司在全球分銷產品。"},{"en":"Profits are distributed among shareholders.","zh-TW":"利潤分配給股東。"},{"en":"The charity distributes food to the homeless.","zh-TW":"慈善機構向無家可歸者分發食物。"}]', '{"noun":"distribution/distributor","verb":"distribute","noun2":"distributor"}', NULL, 4, 2130, 337),
(2131, 'distributed system', '/dɪˈstrɪbjʊtɪd ˈsɪstəm/', 'noun', '{"zh-TW":["分散式系統"],"en":["a network of independent computers that work together as a single system"]}', NULL, 'design a distributed system / distributed system architecture / distributed system failure', '[{"en":"Distributed systems enable horizontal scaling across multiple servers.","zh-TW":"分散式系統允許在多個服務器之間進行水平擴展。"},{"en":"Handling failures gracefully is a core challenge in distributed systems.","zh-TW":"優雅地處理故障是分散式系統的核心挑戰。"}]', '{"adjective":"distributed"}', NULL, 5, 2131, NULL),
(2132, 'distribution', '/ˌdɪstrɪˈbjuːʃən/', 'noun', '{"zh-TW":["分配；配送"],"en":["the process of supplying goods to retailers or customers"]}', NULL, 'distribution network / distribution center', '[{"en":"The company has a wide distribution network across Asia.","zh-TW":"公司在亞洲擁有廣泛的配送網絡。"},{"en":"The distribution center processes thousands of orders daily.","zh-TW":"配送中心每天處理數千個訂單。"}]', '{"verb":"distribute","noun":"distributor","adjective":"distributed"}', NULL, 4, 2132, 26),
(2133, 'distribution center', '/ˌdɪstrɪˈbjuːʃən ˈsentər/', 'noun', '{"zh-TW":["配送中心"],"en":["a warehouse facility that receives and distributes products to retailers"]}', NULL, 'regional distribution center / distribution center operations', '[{"en":"Orders are processed at the regional distribution center.","zh-TW":"訂單在區域配送中心處理。"},{"en":"The new distribution center reduced delivery times by 30%.","zh-TW":"新配送中心將交貨時間縮短了30%。"}]', NULL, NULL, 5, 2133, NULL),
(2134, 'distribution channel', '/ˌdɪstrɪˈbjuːʃən ˈtʃænəl/', 'noun', '{"zh-TW":["銷售通路；配銷渠道"],"en":["the path through which products flow from producer to end consumer"]}', NULL, 'distribution channel strategy / expand distribution channels / direct distribution channel', '[{"en":"The company added e-commerce as a new distribution channel.","zh-TW":"公司將電子商務作為新的銷售通路。"},{"en":"Indirect distribution channels use intermediaries to reach customers.","zh-TW":"間接配銷渠道使用中間商觸達客戶。"}]', '{"plural":"distribution channels"}', NULL, 5, 2134, NULL),
(2135, 'distribution network', '/ˌdɪstrɪˈbjuːʃən ˈnetwɜːrk/', 'noun', '{"zh-TW":["分銷網路"],"en":["the system of channels and intermediaries delivering products to consumers"]}', NULL, 'build a distribution network / expand the distribution network', '[{"en":"The company invested in building a nationwide distribution network.","zh-TW":"公司投資於建立全國性分銷網路。"},{"en":"A strong distribution network is a competitive advantage in retail.","zh-TW":"強大的分銷網路是零售業的競爭優勢。"}]', NULL, NULL, 5, 2135, NULL),
(2136, 'distribution rights', '/ˌdɪstrɪˈbjuːʃən raɪts/', 'noun', '{"zh-TW":["分銷權"],"en":["the exclusive or non-exclusive right to sell a product in a specific territory"]}', NULL, 'hold distribution rights / grant distribution rights', '[{"en":"The company acquired exclusive distribution rights for the product in Asia.","zh-TW":"公司獲得了該產品在亞洲的獨家分銷權。"},{"en":"Distribution rights agreements specify territory, duration, and minimum sales targets.","zh-TW":"分銷權協議規定了地域、期限和最低銷售目標。"}]', NULL, NULL, 5, 2136, NULL),
(2137, 'distributor', '/dɪˈstrɪbjʊtər/', 'noun', '{"zh-TW":["批發商；分銷商"],"en":["a company that supplies goods to retailers or other businesses"]}', NULL, 'exclusive distributor / appoint a distributor / distributor agreement', '[{"en":"The company appointed an exclusive distributor for Southeast Asia.","zh-TW":"公司為東南亞任命了獨家分銷商。"},{"en":"The distributor warehouses products before shipping to retailers.","zh-TW":"分銷商在向零售商發貨前倉儲產品。"}]', '{"plural":"distributors","verb":"distribute"}', NULL, 4, 2137, NULL),
(2138, 'distributor agreement', '/dɪˈstrɪbjuːtər əˈɡriːmənt/', 'noun', '{"zh-TW":["分銷協議"],"en":["a contract governing the rights and obligations of a product distributor"]}', NULL, 'sign a distributor agreement / exclusive distributor agreement', '[{"en":"The distributor agreement grants exclusive rights for three years.","zh-TW":"分銷協議授予了三年的獨家權利。"},{"en":"Terminating a distributor agreement requires compliance with notice periods.","zh-TW":"終止分銷協議需要遵守通知期限。"}]', NULL, NULL, 5, 2138, NULL),
(2139, 'distributor network', '/dɪˈstrɪbjuːtər ˈnetwɜːrk/', 'noun', '{"zh-TW":["經銷商網絡"],"en":["a system of independent distributors who market and sell a company''s products"]}', NULL, 'expand the distributor network / manage the distributor network', '[{"en":"The company expanded its distributor network to 30 new countries.","zh-TW":"公司將其經銷商網絡擴展到了30個新國家。"},{"en":"A strong distributor network accelerates market penetration.","zh-TW":"強大的經銷商網絡加速了市場滲透。"}]', NULL, NULL, 5, 2139, NULL),
(2140, 'disturb', '/dɪˈstɜːrb/', 'verb', '{"zh-TW":["打擾；使不安"],"en":["to interrupt or cause concern"]}', '{"prefix":{"text":"dis-","meaning":"thoroughly (徹底)"},"root":{"text":"turb","meaning":"confuse (混亂)"},"logic":"徹底使其混亂，即「打擾」。"}', 'do not disturb / disturb the peace', '[{"en":"Please do not disturb me while I''m working.","zh-TW":"我工作時請不要打擾我。"},{"en":"The news disturbed her deeply.","zh-TW":"這個消息讓她深感不安。"}]', '{"noun":"disturbance","adjective":"disturbing"}', NULL, 3, 2140, NULL),
(2141, 'diverge', '/daɪˈvɜːrdʒ/', 'verb', '{"zh-TW":["分歧；偏離"],"en":["to go in a different direction; to differ from a standard"]}', NULL, 'diverge from the norm / diverge in opinion / diverge significantly', '[{"en":"The two study groups diverged sharply in their outcomes.","zh-TW":"兩個研究組在結果上明顯分歧。"},{"en":"Expert opinions diverge on the long-term effects of the policy.","zh-TW":"專家意見在該政策的長期效果上存在分歧。"}]', '{"noun":"divergence","adjective":"divergent"}', NULL, 3, 2141, NULL),
(2142, 'divergence', '/daɪˈvɜːrdʒəns/', 'noun', '{"zh-TW":["分歧；差異；偏離"],"en":["the process of moving apart or becoming different"]}', NULL, 'growing divergence / policy divergence / economic divergence', '[{"en":"Divergence in economic performance between regions increased inequality within the country.","zh-TW":"各地區經濟表現的分歧加劇了國內的不平等。"},{"en":"A divergence in monetary policy between central banks affects exchange rates.","zh-TW":"各中央銀行貨幣政策的分歧影響了匯率。"}]', '{"verb":"diverge","adjective":"divergent"}', NULL, 4, 2142, NULL),
(2143, 'diverse', '/daɪˈvɜːrs/', 'adjective', '{"zh-TW":["多樣的；多元的","多樣的；不同的"],"en":["showing great variety","showing a great deal of variety"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"verse","meaning":"turn (轉)"},"logic":"朝不同方向轉的，即「多樣的」。"}', 'diverse workforce/portfolio; diverse population / culturally diverse', '[{"en":"We have a diverse team from many backgrounds.","zh-TW":"我們有來自不同背景的多元團隊。"},{"en":"A diverse portfolio reduces risk.","zh-TW":"多元化的投資組合可以降低風險。"},{"en":"The city has a diverse population.","zh-TW":"這座城市有多元的人口。"},{"en":"We need a more diverse team.","zh-TW":"我們需要一個更多元的團隊。"}]', '{"noun":"diversity/diversification","verb":"diversify","adjective":"diverse"}', NULL, 3, 2143, NULL),
(2144, 'diversification', '/daɪˌvɜːrsɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["多元化"],"en":["the process of expanding into different areas"]}', NULL, 'portfolio diversification / market diversification', '[{"en":"Diversification reduces investment risk.","zh-TW":"多元化降低投資風險。"},{"en":"Market diversification is key to growth.","zh-TW":"市場多元化是成長的關鍵。"}]', '{"noun":"diversification","verb":"diversify","adjective":"diversified"}', NULL, 5, 2144, NULL),
(2145, 'diversification strategy', '/daɪˌvɜːrsɪfɪˈkeɪʃən ˈstrætɪdʒi/', 'noun', '{"zh-TW":["多元化策略"],"en":["a growth strategy expanding into new products or markets to reduce dependence"]}', NULL, 'implement a diversification strategy / related diversification', '[{"en":"The diversification strategy reduced dependency on a single revenue source.","zh-TW":"多元化策略降低了對單一收入來源的依賴。"},{"en":"A related diversification strategy leverages existing capabilities in new areas.","zh-TW":"相關多元化策略在新領域利用了現有能力。"}]', NULL, NULL, 5, 2145, NULL),
(2146, 'diversify', 'daɪˈvɜːrsɪfaɪ', 'verb', '{"zh-TW":["多樣化；分散","多角化"],"en":["to vary or widen range","to expand into new areas"]}', NULL, 'diversify investments/diversify products', '[{"en":"We plan to diversify our product line.","zh-TW":"我們計畫使產品線多元化。"}]', '{"noun":"diversification","adjective":"diversified"}', NULL, 3, 2146, 673),
(2147, 'diversity', '/daɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["多元性；多樣性"],"en":["the inclusion of people from various backgrounds, identities, and experiences"]}', NULL, 'workplace diversity / diversity and inclusion / promote diversity', '[{"en":"The company launched programs to increase diversity in leadership.","zh-TW":"公司推出計劃以增加領導層的多元性。"},{"en":"Diversity fosters creativity and broader perspectives.","zh-TW":"多元性培養創造力和更廣泛的視角。"}]', '{"adjective":"diverse","verb":"diversify"}', NULL, 3, 2147, NULL),
(2148, 'divestiture', '/daɪˈvestɪtʃər/', 'noun', '{"zh-TW":["資產剝離；出售"],"en":["the process of selling off a subsidiary or assets"]}', NULL, 'asset divestiture / forced divestiture', '[{"en":"The divestiture of non-core assets raised $200 million.","zh-TW":"剝離非核心資產籌集了2億美元。"},{"en":"Regulators required a divestiture to approve the merger.","zh-TW":"監管機構要求資產剝離以批准合併。"}]', '{"verb":"divest","adjective":"divested"}', NULL, 4, 2148, 777),
(2149, 'divestment', '/daɪˈvestmənt/', 'noun', '{"zh-TW":["撤資；剝離投資"],"en":["the process of selling off investments or business assets, especially for ethical or financial reasons"]}', NULL, 'fossil fuel divestment / divestment campaign / corporate divestment', '[{"en":"Many universities faced pressure from students to pursue divestment from fossil fuel companies.","zh-TW":"許多大學面臨學生的壓力，要求對化石燃料公司進行撤資。"},{"en":"The divestment of non-core subsidiaries generated capital for reinvestment in the main business.","zh-TW":"剝離非核心子公司的投資為主業的再投資帶來了資本。"}]', '{"verb":"divest"}', NULL, 4, 2149, NULL);